conversion:
// 工资支付暂行规定 第十一条、第十二条: no wage for days not worked. A fixed allowance is paid for the days the salary pays: it falls by the period's paid share on its own line, and BASIC stays the salary alone.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const rate = Number(get(terms, 'rate.amount', 0));
const amount = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const coverage = ctx.run.salary_coverage;
const off = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
let working = 0;
for (let date = coverage.from; date <= coverage.to; date = add_days(date, 1)) if (!off.includes(weekday(date))) working += 1;
const hours = working * Number(get(terms, 'normal_hours_per_day', 8));
const salary = unit === 'DAILY' ? rate * working : unit === 'HOURLY' ? rate * hours : rate;
return salary > 0 ? amount * ctx.paid_share : amount;

eligibility:
const employerRegion = String(get(ctx.subject.employer, 'entity_extension_data.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
if (region !== ctx.lookup.region) return false;
if (!ctx.lookup.months.includes(Number(ctx.as_of.slice(5, 7)))) return false;
return (ctx.work_events ?? []).some((event) => {
  if (get(event, 'code', '') !== 'HIGH_TEMPERATURE') return false;
  const from = String(get(event, 'from', ''));
  const to = get(event, 'to', null);
  return from !== '' && from <= ctx.as_of && ctx.as_of <= String(to ?? from);
});
